import * as T from './vendor/three.module.js';
import {OrbitControls} from './vendor/OrbitControls.js';
import {makeRenderPart} from './render-part.js';
import {airplaneShapes} from './shape-builder.js';
import {BY_ID} from './engine.js';
import {icon} from './icons.js';
const COLORS=['#e0e6ed','#57b5ff','#57b5ff','#ffad47','#ffad47','#ffad47','#73e6ce'];
export function shapeBuilderDialog({model,showDialog,commit}){
 let shapes=[{name:'Box',kind:'box',center:[0,150,0],size:[300,150,150]}],rod='r-blue',braced=true,selected=0,result=null,worker=null,closed=false,frame,drag=null,view='shapes';const history=[];
 showDialog(`<h2>Grid shell · experimental</h2><div class="shape-workspace"><div class="shape-stage"><div class="shape-toolbar"><button data-shape-view="shapes" aria-pressed="true">Shapes</button><button data-shape-view="parts" aria-pressed="false" disabled>K’NEX</button><button id="shape-fit" aria-label="Fit shapes">${icon('frame')}</button><button id="shape-top">Top</button><button id="shape-3d">3D</button></div><div id="shape-canvas"></div><div class="shape-bottom"><span id="shape-status" role="status">Drag a shape to move it · scroll to zoom</span><button id="shape-convert" class="button">Build grid shell</button><button id="shape-apply" class="button" disabled>Add to model</button></div></div><aside class="shape-controls"><div class="shape-presets"><button data-shape-preset="airplane">Aircraft grid test</button><button data-shape-preset="body">Rounded body</button><button data-shape-preset="box">Box</button></div><div id="shape-list" aria-label="Rough shapes"></div><div class="shape-add"><button data-shape-add="box">+ Box</button><button data-shape-add="ellipsoid">+ Round</button><button data-shape-add="taper">+ Taper</button><button id="shape-undo" aria-label="Undo shape edit" disabled>↶</button></div><div id="shape-fields"></div><label>Rod spacing <select id="shape-rod" aria-label="Shape frame rod length">${['r-white','r-blue','r-yellow','r-red'].map(id=>`<option value="${id}" ${id===rod?'selected':''}>${BY_ID[id].name} · ${Math.round((BY_ID[id].length+20.2)*10)/10} mm cells</option>`).join('')}</select></label><label><input id="shape-braced" type="checkbox" checked> Diagonal braces</label><p id="shape-error" role="alert"></p><details><summary>Grid limitations</summary><p>This is a grid-shell experiment, not a manual-based model builder. Volumes share one stock-rod grid. Curves and tapers become stepped surfaces. Each edge uses an actual rod; flat nodes use 8-way connectors, spatial nodes use interlocked blue pairs.</p><p>Move or resize the shapes, then convert. Thin or detached shapes are reported. Conversion checks real sockets and modeled collisions. It does not certify strength, balance or flight. Added frames stay individually editable.</p><p>This first version uses axis-aligned volumes. Arbitrary mesh import and automatic mechanical design are not available.</p></details></aside></div>`);
 const dialog=document.querySelector('#dialog'),$=s=>dialog.querySelector(s);dialog.classList.add('shape-dialog');
 const scene=new T.Scene();scene.background=new T.Color('#202934');scene.add(new T.HemisphereLight(0xffffff,0x617083,3));const light=new T.DirectionalLight(0xffffff,3);light.position.set(-400,700,500);scene.add(light);
 const guides=new T.Group(),parts=new T.Group();scene.add(guides,parts);const camera=new T.PerspectiveCamera(38,1,.1,50000),renderer=new T.WebGLRenderer({antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.outputColorSpace=T.SRGBColorSpace;$('#shape-canvas').append(renderer.domElement);renderer.domElement.setAttribute('aria-label','Rough shape editor. Drag shapes to move; drag empty space to orbit.');
 const controls=new OrbitControls(camera,renderer.domElement);controls.enableDamping=true;const ray=new T.Raycaster(),pointer=new T.Vector2();
 function remember(){history.push({shapes:structuredClone(shapes),rod,braced});if(history.length>30)history.shift();$('#shape-undo').disabled=false;}
 function clearParts(){for(const child of parts.children)child.dispose?.();parts.clear();}
 function invalidate(){worker?.terminate();worker=null;result=null;view='shapes';clearParts();$('#shape-apply').disabled=true;$('[data-shape-view="parts"]').disabled=true;$('#shape-convert').disabled=false;$('#shape-error').textContent='';$('#shape-status').textContent='Shapes changed · convert to update';setView();}
 function setView(){guides.visible=view==='shapes';parts.visible=view==='parts';dialog.querySelectorAll('[data-shape-view]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.shapeView===view)));}
 function geometry(s){if(s.kind==='ellipsoid')return new T.SphereGeometry(.5,24,16);const g=new T.BoxGeometry(1,1,1);if(s.kind==='taper'){const a=g.attributes.position,axis=s.axis??2;for(let i=0;i<a.count;i++){const v=new T.Vector3().fromBufferAttribute(a,i),t=v.getComponent(axis)+.5,scale=1-(1-s.tipScale)*(s.reverse?1-t:t);for(let j=0;j<3;j++)if(j!==axis)v.setComponent(j,v.getComponent(j)*scale);a.setXYZ(i,v.x,v.y,v.z);}a.needsUpdate=true;g.computeVertexNormals();}return g;}
 function drawGuides(){for(const child of guides.children){child.geometry.dispose();child.material.dispose();}guides.clear();shapes.forEach((s,i)=>{const mesh=new T.Mesh(geometry(s),new T.MeshStandardMaterial({color:COLORS[i%COLORS.length],transparent:true,opacity:i===selected?.75:.3,roughness:.5,depthWrite:false,emissive:i===selected?'#154c50':'#000000'}));mesh.position.fromArray(s.center);mesh.scale.fromArray(s.size);mesh.userData.index=i;guides.add(mesh);});}
 function fit(direction=[1,.8,1.4]){const bounds=new T.Box3().setFromObject(view==='parts'?parts:guides),center=bounds.getCenter(new T.Vector3()),radius=Math.max(40,bounds.getBoundingSphere(new T.Sphere()).radius);controls.target.copy(center);camera.position.copy(center).addScaledVector(new T.Vector3(...direction).normalize(),radius/Math.sin(19*Math.PI/180)*.85);camera.lookAt(center);controls.update();}
 function renderList(){const list=$('#shape-list');list.replaceChildren();shapes.forEach((s,i)=>{const row=document.createElement('div'),button=document.createElement('button'),remove=document.createElement('button');row.className='shape-row';button.textContent=s.name;button.style.setProperty('--shape-color',COLORS[i%COLORS.length]);button.setAttribute('aria-pressed',String(i===selected));button.onclick=()=>{selected=i;drawGuides();renderList();renderFields();};remove.textContent='×';remove.setAttribute('aria-label','Remove '+s.name);remove.disabled=shapes.length===1;remove.onclick=()=>{remember();shapes.splice(i,1);selected=Math.min(selected,shapes.length-1);invalidate();refresh();};row.append(button,remove);list.append(row);});}
 function renderFields(){const s=shapes[selected];$('#shape-fields').innerHTML=`<label>Name <input id="shape-name" aria-label="Shape name" maxlength="60"></label>${['size','center'].map(kind=>`<fieldset><legend>${kind==='size'?'Size':'Position'} · mm</legend><div class="shape-vector">${['X','Y','Z'].map((a,i)=>`<label>${a}<input data-shape-vector="${kind},${i}" aria-label="Shape ${kind} ${a}" type="number" step="37.5" ${kind==='size'?'min="1"':''} max="10000" value="${Math.round(s[kind][i]*100)/100}"></label>`).join('')}</div></fieldset>`).join('')}`+(s.kind==='taper'?'<label>Taper axis <select id="shape-axis" aria-label="Taper axis"><option value="0">X</option><option value="1">Y</option><option value="2">Z</option></select></label><label>Tip size <input id="shape-tip" aria-label="Taper tip size" type="range" min="0.1" max="1" step="0.1"></label><label><input id="shape-reverse" type="checkbox"> Reverse taper</label>':'');
 $('#shape-name').value=s.name;$('#shape-name').onchange=e=>{remember();s.name=e.target.value.trim()||'Shape';invalidate();renderList();};dialog.querySelectorAll('[data-shape-vector]').forEach(input=>input.onchange=()=>{const [kind,i]=input.dataset.shapeVector.split(','),value=Number(input.value);if(!input.value||!Number.isFinite(value)||Math.abs(value)>10000||kind==='size'&&value<=0){$('#shape-error').textContent='Enter a valid size or position.';input.value=s[kind][+i];return;}remember();s[kind][+i]=value;invalidate();drawGuides();});if(s.kind==='taper'){$('#shape-axis').value=s.axis;$('#shape-tip').value=s.tipScale;$('#shape-reverse').checked=!!s.reverse;$('#shape-axis').onchange=e=>{remember();s.axis=Number(e.target.value);invalidate();drawGuides();};$('#shape-tip').onchange=e=>{remember();s.tipScale=Number(e.target.value);invalidate();drawGuides();};$('#shape-reverse').onchange=e=>{remember();s.reverse=e.target.checked;invalidate();drawGuides();};}}
 function refresh(){drawGuides();renderList();renderFields();$('#shape-rod').value=rod;$('#shape-braced').checked=braced;}
 function drawParts(m){clearParts();const buckets=new Map();for(const p of m.parts){const object=makeRenderPart(p.type,p);object.position.fromArray(p.pos);object.quaternion.fromArray(p.quat);object.updateMatrixWorld(true);object.traverse(o=>{if(!o.isMesh)return;const key=o.geometry.uuid+':'+o.material.uuid;if(!buckets.has(key))buckets.set(key,{geometry:o.geometry,material:o.material,matrices:[]});buckets.get(key).matrices.push(o.matrixWorld.clone());});}for(const b of buckets.values()){const mesh=new T.InstancedMesh(b.geometry,b.material,b.matrices.length);b.matrices.forEach((m,i)=>mesh.setMatrixAt(i,m));mesh.instanceMatrix.needsUpdate=true;parts.add(mesh);}}
 $('#shape-convert').onclick=()=>{worker?.terminate();$('#shape-error').textContent='';$('#shape-convert').disabled=true;$('#shape-apply').disabled=true;$('#shape-status').textContent='Converting shapes · checking sockets and collisions…';worker=new Worker(new URL('./shape-builder-worker.js',import.meta.url),{type:'module'});worker.onmessage=({data})=>{worker?.terminate();worker=null;if(closed)return;$('#shape-convert').disabled=false;if(data.error){$('#shape-error').textContent=data.error;$('#shape-status').textContent='Conversion blocked';return;}result=data;drawParts(data.preview);view='parts';setView();fit();$('[data-shape-view="parts"]').disabled=false;$('#shape-apply').disabled=false;$('#shape-status').textContent=`${data.summary.parts} parts · ${data.summary.connections} connections · ${data.summary.size.map(Math.round).join(' × ')} mm`;};worker.onerror=()=>{worker?.terminate();worker=null;$('#shape-error').textContent='Conversion failed. Try fewer or smaller shapes.';$('#shape-convert').disabled=false;};worker.postMessage({source:model,options:{name:'Shape-built frame',rod,braced,shapes}});};
 $('#shape-apply').onclick=()=>{if(result){commit(result.model);dialog.close();}};
 $('#shape-rod').onchange=e=>{remember();rod=e.target.value;invalidate();};$('#shape-braced').onchange=e=>{remember();braced=e.target.checked;invalidate();};$('#shape-undo').onclick=()=>{const prev=history.pop();if(!prev)return;({shapes,rod,braced}=prev);selected=Math.min(selected,shapes.length-1);invalidate();refresh();$('#shape-undo').disabled=!history.length;};
 dialog.querySelectorAll('[data-shape-preset]').forEach(b=>b.onclick=()=>{remember();const preset=b.dataset.shapePreset;shapes=preset==='airplane'?airplaneShapes(rod):[{name:preset==='body'?'Rounded body':'Box',kind:preset==='body'?'ellipsoid':'box',center:[0,150,0],size:[450,150,150]}];selected=0;invalidate();refresh();fit();});
 dialog.querySelectorAll('[data-shape-add]').forEach(b=>b.onclick=()=>{if(shapes.length>=24)return;remember();const kind=b.dataset.shapeAdd;shapes.push({name:kind==='box'?'Box':kind==='taper'?'Taper':'Rounded shape',kind,center:[0,225,0],size:[150,150,150],...(kind==='taper'?{axis:2,tipScale:.5}:{})});selected=shapes.length-1;invalidate();refresh();});
 dialog.querySelectorAll('[data-shape-view]').forEach(b=>b.onclick=()=>{view=b.dataset.shapeView;setView();fit();});$('#shape-fit').onclick=()=>fit();$('#shape-top').onclick=()=>fit([.0001,1,0]);$('#shape-3d').onclick=()=>fit();
 function point(e){const rect=renderer.domElement.getBoundingClientRect();pointer.set((e.clientX-rect.left)/rect.width*2-1,-(e.clientY-rect.top)/rect.height*2+1);ray.setFromCamera(pointer,camera);}
 renderer.domElement.addEventListener('pointerdown',e=>{if(view!=='shapes'||e.button!==0)return;point(e);const hit=ray.intersectObjects(guides.children)[0];if(!hit)return;e.stopImmediatePropagation();selected=hit.object.userData.index;remember();const plane=new T.Plane().setFromNormalAndCoplanarPoint(camera.getWorldDirection(new T.Vector3()),hit.point);drag={plane,start:hit.point.clone(),center:new T.Vector3(...shapes[selected].center)};controls.enabled=false;renderer.domElement.setPointerCapture(e.pointerId);drawGuides();renderList();renderFields();},{capture:true});
 renderer.domElement.addEventListener('pointermove',e=>{if(!drag)return;point(e);const hit=ray.ray.intersectPlane(drag.plane,new T.Vector3());if(!hit)return;const p=hit.sub(drag.start).add(drag.center),step=(BY_ID[rod].length+20.2)/2;shapes[selected].center=p.toArray().map(v=>Math.max(-10000,Math.min(10000,Math.round(v/step)*step)));invalidate();drawGuides();renderFields();});
 const endDrag=()=>{drag=null;controls.enabled=true;};renderer.domElement.addEventListener('pointerup',endDrag);renderer.domElement.addEventListener('pointercancel',endDrag);
 const observer=new ResizeObserver(()=>{const r=$('#shape-canvas').getBoundingClientRect();renderer.setSize(Math.max(1,r.width),Math.max(1,r.height));camera.aspect=r.width/Math.max(1,r.height);camera.updateProjectionMatrix();});observer.observe($('#shape-canvas'));
 dialog.addEventListener('close',()=>{closed=true;worker?.terminate();cancelAnimationFrame(frame);observer.disconnect();controls.dispose();clearParts();for(const child of guides.children){child.geometry.dispose();child.material.dispose();}renderer.dispose();renderer.forceContextLoss();dialog.classList.remove('shape-dialog');},{once:true});
 function animate(){if(closed)return;controls.update();renderer.render(scene,camera);frame=requestAnimationFrame(animate);}refresh();fit();animate();
}
